function initAudio(){if(!audio)audio=new(window.AudioContext||window.webkitAudioContext)();audio.resume();if(!ambience.length){let gain=audio.createGain();gain.gain.value=muted?0:.055;gain.connect(audio.destination);for(let f of [65.4,98.1,131.3]){let o=audio.createOscillator();o.type='sine';o.frequency.value=f;o.connect(gain);o.start()}const buffer=audio.createBuffer(1,audio.sampleRate*3,audio.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++)data[i]=(Math.random()*2-1)*.3;let wind=audio.createBufferSource();wind.buffer=buffer;wind.loop=true;let filter=audio.createBiquadFilter();filter.type='lowpass';filter.frequency.value=340;wind.connect(filter);filter.connect(gain);wind.start();ambience.push(gain)}}
