canvas.addEventListener('pointerdown',e=>{if(!playing)return;const r=canvas.getBoundingClientRect(),x=e.clientX-r.left,y=e.clientY-r.top;shots++;let index=-1;for(let i=ghosts.length-1;i>=0;i--)if(Math.hypot(x-ghosts[i].cx,y-ghosts[i].cy)<ghosts[i].r*1.2){index=i;break}if(index<0){combo=0;$('#combo').textContent='';tone(-1);labels.push({x,y,text:'MISS',color:'#c8b9ce',born:performance.now()});return}const o=ghosts.splice(index,1)[0];hits++;combo++;let multi=Math.min(3,1+Math.floor(combo/5)),points=types[o.type].points*multi;score+=points;$('#score').textContent=String(score).padStart(4,'0');$('#combo').textContent=combo>1?`${combo} COMBO ${multi>1?'· ×'+multi:''}`:'';tone(o.type);labels.push({x,y,text:'+'+points,color:types[o.type].color,born:performance.now()});for(let i=0;i<16;i++)particles.push({x,y,vx:(Math.random()-.5)*5,vy:(Math.random()-.5)*5-1,life:1,color:types[o.type].color})});
let previous=0;function frame(t){const dt=Math.min(50,t-previous||16);previous=t;rafTime=t;scene(t);if(playing){remaining=Math.max(0,Math.ceil((end-t)/1000));$('#time').innerHTML=remaining+'<em>s</em>';if(t>=end)finish();else if(t-lastSpawn>Math.max(560,1050-(60-remaining)*6)){if(ghosts.length<9)spawn();lastSpawn=t}ghosts=ghosts.filter(o=>{if(t-o.born>o.life){combo=0;$('#combo').textContent='';return false}return true})}for(const o of ghosts){if(playing){o.x+=o.vx*dt;if(o.x<.08||o.x>.92)o.vx*=-1}ghost(o,t)}for(let i=particles.length-1;i>=0;i--){const p=particles[i];p.x+=p.vx*dt/16;p.y+=p.vy*dt/16;p.vy+=.08*dt/16;p.life-=dt/600;ctx.globalAlpha=Math.max(0,p.life);ellipse(p.x,p.y,3,3,p.color);if(p.life<=0)particles.splice(i,1)}ctx.globalAlpha=1;labels=labels.filter(l=>t-l.born<800);for(const l of labels){const age=(t-l.born)/800;ctx.globalAlpha=1-age;ctx.fillStyle=l.color;ctx.font='800 26px sans-serif';ctx.textAlign='center';ctx.fillText(l.text,l.x,l.y-age*55)}ctx.globalAlpha=1;requestAnimationFrame(frame)}
